begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('d3520000-0000-4000-8000-000000000001','registration-owner@example.test',now()),
 ('d3520000-0000-4000-8000-000000000002','registration-seller@example.test',now()),
 ('d3520000-0000-4000-8000-000000000003','registration-staff@example.test',now()),
 ('d3520000-0000-4000-8000-000000000004','registration-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Synthetic registration','registration-test',gen_random_uuid())::text,true);
select is(seller_registration_settings(current_setting('test.tenant')::uuid)->>'enabled','false','registration defaults off');
select throws_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'enable')$$,'P0001','AGREEMENT_REQUIRED','publish an agreement before enabling');
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic agreement','Synthetic terms to review','en',true)::text,true);
select set_config('test.setting',gen_random_uuid()::text,true);
select lives_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,current_setting('test.setting')::uuid,null,'enable')$$,'owner enables registration');
select set_config('test.token',seller_registration_settings(current_setting('test.tenant')::uuid)->>'token',true);
select lives_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,current_setting('test.setting')::uuid,null,'enable')$$,'setting retry stable');
select throws_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'disable')$$,'P0001','REGISTRATION_CHANGED','stale setting rejected');
select create_invitation(current_setting('test.tenant')::uuid,'registration-staff@example.test','staff',repeat('e',64));
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000003","role":"authenticated"}';
select accept_invitation(repeat('e',64));
select throws_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.setting')::uuid,'enable')$$,'42501','FORBIDDEN','staff cannot enable');
select lives_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.setting')::uuid,'rotate')$$,'staff can rotate');
select set_config('test.token2',seller_registration_settings(current_setting('test.tenant')::uuid)->>'token',true);
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select seller_registration_settings(current_setting('test.tenant')::uuid)$$,'42501','FORBIDDEN','seller cannot read store settings');
select is(seller_registration_entry(current_setting('test.token'),'en')->>'state','unavailable','old link revoked');
select is(seller_registration_entry(current_setting('test.token2'),'en')->>'state','form','valid link shows agreement only after authentication');
select set_config('test.application',gen_random_uuid()::text,true);
select throws_ok($$select submit_seller_registration(current_setting('test.token2'),current_setting('test.application')::uuid,'Synthetic seller','0700000000',current_setting('test.agreement')::uuid,null,false)$$,'P0001','INVALID_INPUT','personal agreement acceptance required');
select lives_ok($$select submit_seller_registration(current_setting('test.token2'),current_setting('test.application')::uuid,'Synthetic seller','0700000000',current_setting('test.agreement')::uuid,null,true)$$,'seller applies');
select lives_ok($$select submit_seller_registration(current_setting('test.token2'),current_setting('test.application')::uuid,'Synthetic seller','0700000000',current_setting('test.agreement')::uuid,null,true)$$,'application retry stable');
select throws_ok($$select submit_seller_registration(current_setting('test.token2'),current_setting('test.application')::uuid,'Different','0700000000',current_setting('test.agreement')::uuid,null,true)$$,'P0001','REQUEST_CONFLICT','changed replay rejected');
select is(seller_registration_entry(current_setting('test.token2'),'en')->>'state','pending','pending entry');
select is(jsonb_array_length(my_seller_registrations()),1,'pending visible to applicant');
select is(jsonb_array_length(my_seller_accounts()),0,'pending creates no seller access');
select is((select count(*) from tenant_members where user_id=auth.uid()),0::bigint,'pending grants no store membership');
select throws_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application')::uuid,true)$$,'42501','FORBIDDEN','seller cannot self-approve');
select throws_ok($$select * from seller_registrations$$,'42501',null,'direct contact reads denied');
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000004","role":"authenticated"}';
select is(jsonb_array_length(my_seller_registrations()),0,'other account cannot see application');
select throws_ok($$select store_seller_registrations(current_setting('test.tenant')::uuid,0)$$,'42501','FORBIDDEN','other store cannot review');
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000003","role":"authenticated"}';
select is(store_seller_registrations(current_setting('test.tenant')::uuid,0)->>'total','1','staff sees pending application');
select set_config('test.review',gen_random_uuid()::text,true);
select set_config('test.seller',review_seller_registration(current_setting('test.tenant')::uuid,current_setting('test.review')::uuid,current_setting('test.application')::uuid,true)::text,true);
select lives_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,current_setting('test.review')::uuid,current_setting('test.application')::uuid,true)$$,'approval retry stable');
select throws_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application')::uuid,false)$$,'P0001','REGISTRATION_REVIEWED','cannot reverse decision in place');
select is((select count(*) from seller_agreement_evidence where seller_id=current_setting('test.seller')::uuid and recorded_by='d3520000-0000-4000-8000-000000000002' and source='seller_portal'),1::bigint,'evidence identifies seller, not approving staff');
reset role;
select is((select count(*) from seller_store_mail_consents where seller_id=current_setting('test.seller')::uuid),0::bigint,'no automatic email subscription');
select throws_ok($$update seller_registration_reviews set approved=false$$,'55000','IMMUTABLE_AGREEMENT_RECORD','decisions immutable');
select is((select agreement_text->>'body' from seller_registrations where id=current_setting('test.application')::uuid),'Synthetic terms to review','exact accepted text retained');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(seller_registration_entry(current_setting('test.token2'),'en')->>'state','existing','approved seller led to existing record');
select is(jsonb_array_length(my_seller_accounts()),1,'approval grants ordinary seller portal access');
set local role anon;
select throws_ok($$select seller_registration_entry(current_setting('test.token2'),'en')$$,'42501',null,'no lookup before login');
reset role;
-- A concurrent staff registration must be reused at approval, not duplicated.
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000004","role":"authenticated"}';
select set_config('test.application2',gen_random_uuid()::text,true);
select submit_seller_registration(current_setting('test.token2'),current_setting('test.application2')::uuid,'Synthetic second seller','0700000001',current_setting('test.agreement')::uuid,null,true);
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.existing',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Staff entered',' REGISTRATION-OUTSIDER@example.test ','0700000001')::text,true);
select is(review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application2')::uuid,true),current_setting('test.existing')::uuid,'approval rechecks email and reuses staff-created seller');
reset role;
select is((select created_seller from seller_registration_reviews where registration_id=current_setting('test.application2')::uuid),false,'existing seller is not eligible as newly self-registered');
select is((select count(*) from sellers where tenant_id=current_setting('test.tenant')::uuid and lower(trim(email))='registration-outsider@example.test'),1::bigint,'only one matching seller');
-- Ambiguous matches are held for staff resolution, including after submission.
insert into auth.users(id,email,email_confirmed_at) values ('d3520000-0000-4000-8000-000000000005','registration-ambiguous@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000005","role":"authenticated"}';
select set_config('test.application3',gen_random_uuid()::text,true);
select submit_seller_registration(current_setting('test.token2'),current_setting('test.application3')::uuid,'Synthetic third seller','0700000002',current_setting('test.agreement')::uuid,null,true);
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated"}';
select register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Ambiguous A','registration-ambiguous@example.test','');
select register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Ambiguous B','registration-ambiguous@example.test','');
select throws_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application3')::uuid,true)$$,'P0001','REGISTRATION_AMBIGUOUS','ambiguous match never selected arbitrarily');
select lives_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application3')::uuid,false)$$,'ambiguous application can be rejected');
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000005","role":"authenticated"}';
select is(my_seller_registrations()->0->>'state','rejected','applicant sees rejection');
select is(jsonb_array_length(my_seller_accounts()),0,'ambiguous identity does not gain seller access');
-- A new agreement invalidates an unsubmitted form; the accepted text stays immutable.
reset role;
insert into auth.users(id,email,email_confirmed_at) values ('d3520000-0000-4000-8000-000000000006','registration-new@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.newagreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.agreement')::uuid,'New terms','Current terms','en',true)::text,true);
select set_config('test.translation',publish_agreement_translation(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.newagreement')::uuid,'Translated terms','Translated current terms','sv')::text,true);
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000006","role":"authenticated"}';
select throws_ok($$select submit_seller_registration(current_setting('test.token2'),gen_random_uuid(),'Synthetic new','0700000003',current_setting('test.agreement')::uuid,null,true)$$,'P0001','AGREEMENT_CHANGED','stale unaccepted agreement rejected');
select is(seller_registration_entry(current_setting('test.token2'),'sv')->'agreement'->>'body','Translated current terms','translated agreement shown');
select set_config('test.application4',gen_random_uuid()::text,true);
select submit_seller_registration(current_setting('test.token2'),current_setting('test.application4')::uuid,'Synthetic new','0700000003',current_setting('test.newagreement')::uuid,current_setting('test.translation')::uuid,true);
reset role;
select is((select agreement_text->>'body' from seller_registrations where id=current_setting('test.application4')::uuid),'Translated current terms','exact translation retained');
update auth.users set email='registration-changed@example.test' where id='d3520000-0000-4000-8000-000000000006';
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application4')::uuid,true)$$,'P0001','REGISTRATION_EMAIL_CHANGED','changed account email is not silently linked');
select is(delete_unused_seller_agreement(current_setting('test.tenant')::uuid,current_setting('test.newagreement')::uuid)->>'ok','false','pending agreement protected from deletion');
-- Staff may close but cannot reopen, and pending submissions remain available.
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000003","role":"authenticated"}';
select set_config('test.currentsetting',seller_registration_settings(current_setting('test.tenant')::uuid)->>'id',true);
select set_config('test.closed',set_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.currentsetting')::uuid,'disable')::text,true);
select throws_ok($$select set_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.closed')::uuid,'rotate')$$,'P0001','REGISTRATION_DISABLED','rotation cannot reopen a disabled link');
select is(store_seller_registrations(current_setting('test.tenant')::uuid,0)->>'total','1','closing does not lose pending applications');
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000006","role":"authenticated"}';
select is(seller_registration_entry(current_setting('test.token2'),'en')->>'state','unavailable','closed link no longer admits sellers');
select throws_ok($$select submit_seller_registration(current_setting('test.token2'),gen_random_uuid(),'Synthetic new','0700000003',current_setting('test.newagreement')::uuid,null,true)$$,'P0001','REGISTRATION_DISABLED','direct submission cannot bypass closure');
-- Existing GDPR contact erasure also covers the application; legal text stays.
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.privacy',seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'revision',true);
select lives_ok($$select erase_seller_contact(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.privacy'),'Retain accepted agreement for review',current_date+30,true)$$,'contact erasure includes registration');
reset role;
select is((select name||email||phone from seller_registrations where id=current_setting('test.application')::uuid),'','application contacts erased');
select is((select agreement_text->>'body' from seller_registrations where id=current_setting('test.application')::uuid),'Synthetic terms to review','accepted text remains after contact erasure');
-- Both email confirmation and MFA are enforced by SQL, not just the page.
update auth.users set email_confirmed_at=null where id='d3520000-0000-4000-8000-000000000006';
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000006","role":"authenticated"}';
select throws_ok($$select my_seller_registrations()$$,'42501','AUTH_REQUIRED','unverified account blocked');
reset role;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),'d3520000-0000-4000-8000-000000000001','totp','verified',now(),now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}';
select throws_ok($$select seller_registration_settings(current_setting('test.tenant')::uuid)$$,'42501','AUTH_REQUIRED','settings require existing MFA');
select throws_ok($$select review_seller_registration(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.application4')::uuid,false)$$,'42501','AUTH_REQUIRED','review requires MFA');
set local "request.jwt.claims"='{"sub":"d3520000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}';
select lives_ok($$select seller_registration_settings(current_setting('test.tenant')::uuid)$$,'completed MFA accepted');
reset role;
select * from finish();
rollback;
